(()=>{const button=document.getElementById('camera'),notice=document.getElementById('notice'),video=document.getElementById('video');let detector,hands,stream,timer,lastSeen=0,lastFrame=-1,gesture=[],lastSwipe=0,generation=0;
function message(text,error=false){notice.textContent=text;notice.classList.toggle('error',error)}
function stop(){generation++;clearInterval(timer);stream?.getTracks().forEach(t=>t.stop());stream=null;video.srcObject=null;window.room.face=false;button.setAttribute('aria-pressed','false');button.setAttribute('aria-label','Enable camera');document.body.classList.remove('camera-on');gesture=[]}
button.onclick=async()=>{if(stream){stop();message('Camera off');return}button.disabled=true;const current=++generation;message('Loading local face and hand tracking');try{const vision=await import('https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@0.10.21/vision_bundle.mjs');const files=await vision.FilesetResolver.forVisionTasks('https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@0.10.21/wasm');if(!detector)detector=await vision.FaceDetector.createFromOptions(files,{baseOptions:{modelAssetPath:'https://storage.googleapis.com/mediapipe-models/face_detector/blaze_face_short_range/float16/1/blaze_face_short_range.tflite'},runningMode:'VIDEO',minDetectionConfidence:.6});if(!hands){try{hands=await vision.HandLandmarker.createFromOptions(files,{baseOptions:{modelAssetPath:'https://storage.googleapis.com/mediapipe-models/hand_landmarker/hand_landmarker/float16/1/hand_landmarker.task'},runningMode:'VIDEO',numHands:1})}catch{message('Hand tracking unavailable. Swipe on the screen to change the artwork.',true)}}stream=await navigator.mediaDevices.getUserMedia({video:{width:480,height:360,facingMode:'user'},audio:false});if(current!==generation){stop();return}video.srcObject=stream;await video.play();document.body.classList.add('camera-on');button.setAttribute('aria-pressed','true');button.setAttribute('aria-label','Stop camera');lastSeen=0;lastFrame=-1;timer=setInterval(()=>{if(video.readyState<2||lastFrame===video.currentTime)return;lastFrame=video.currentTime;try{const now=performance.now(),result=detector.detectForVideo(video,now);if(result.detections.length)lastSeen=now;window.room.face=lastSeen>0&&now-lastSeen<1100;if(hands){const h=hands.detectForVideo(video,now).landmarks[0];if(h){const point={x:1-h[9].x,y:h[9].y,t:now};gesture.push(point);gesture=gesture.filter(q=>now-q.t<650);let first=gesture[0];if(gesture.length>=3&&point.x-first.x>.22&&Math.abs(point.y-first.y)<.22&&now-lastSwipe>1400){window.regenerateArt?.();lastSwipe=now;gesture=[]}}else gesture=[]}}catch{stop();message('Tracking stopped. Tap the camera icon to retry.',true)}},140)}catch(e){stop();message(e.name==='NotAllowedError'?'Camera permission is needed. Enable it in your browser, then tap the camera icon.':'Camera tracking could not start. Check your connection and tap the camera icon to retry.',true)}finally{button.disabled=false}};addEventListener('pagehide',stop)})();
